import type { Command } from "commander";
import { markMutating } from "../command-annotations.js";
import {
  AlignmentIndex,
  createNote,
  createTask,
  getAuthor,
  initContext,
  type KspecContext,
  type LoadedSpecItem,
  type LoadedTask,
  loadAllItems,
  loadAllTasks,
  ReferenceIndex,
